import java.io.*;
import java.util.*;

public class tr0_variant4 {
    private static final int MOD = 998244353;

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();

        if (k >= n) {
            System.out.println(0);
            return;
        }

        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        if (k == 0) {
            System.out.println(fact[n]);
            return;
        }

        int c = n - (int) k;
        long result = fact[n];
        result = result * modPow(fact[c], MOD - 2) % MOD;
        result = result * modPow(fact[n - c], MOD - 2) % MOD;

        long sum = 0;
        for (int i = 0; i <= c; i++) {
            long comb = fact[c] * modPow(fact[i], MOD - 2) % MOD;
            comb = comb * modPow(fact[c - i], MOD - 2) % MOD;
            long power = modPow(c - i, n);
            long term = comb * power % MOD;
            sum = (sum + (i % 2 == 0 ? 1 : -1) * term + MOD) % MOD;
        }

        result = result * sum % MOD * 2 % MOD;
        System.out.println(result);
    }

    private static long modPow(long base, long exp) {
        base %= MOD;
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }

    static class Scanner {
        private BufferedReader br;
        private StringTokenizer st;

        public Scanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public Scanner(String fileName) throws IOException {
            br = new BufferedReader(new FileReader(fileName));
        }

        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        public String next() throws IOException {
            return nextToken();
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        public char nextChar() throws IOException {
            return nextToken().charAt(0);
        }

        public boolean ready() throws IOException {
            return br.ready();
        }

        public void pause(int milliseconds) throws InterruptedException {
            Thread.sleep(milliseconds);
        }
    }
